param([switch]$ScopeOnly,[switch]$ExportOnly,[string]$OutputDirectory='')
. "$PSScriptRoot/RagnvaldSecondBattlePredecessor.ps1"
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..")
function Block([string]$s,[string]$start){$a=$s.IndexOf($start);if($a -lt 0){throw "Missing $start"};$b=$s.IndexOf('{',$a)+1;$depth=1;while($depth -and $b -lt $s.Length){$depth+=([int]($s[$b] -eq '{'))-([int]($s[$b] -eq '}'));++$b};if($depth){throw "Unclosed $start"};$s.Substring($a,$b-$a)}
function Shape([string]$s){([regex]::Replace($s,'(?s)/\*.*?\*/','') -replace '//[^\n]*','') -replace '\s',''}
$path='src/server/scripts/Scenario/Artifacts/Warrior/Intro/wars_intro_scenario.cpp';$source=Get-PreRagnvaldSecondBattleSource $path (Get-Content "$repo/$path" -Raw);$source=$source.Replace("`r",'');$old=(& git -C $repo show "1531780a2:$path") -join "`n";if($LASTEXITCODE){throw 'Pinned ritual baseline missing'}
$actor=Block $source 'class npc_danica_the_reclaimer :';$previous=Block $old 'class npc_danica_the_reclaimer :'
if((Shape $source.Replace($actor,$previous).Replace('#include "ritual_transition.h"','')) -cne (Shape $old)){throw 'Other opening/Warrior actor/combat/scene/handoff changed'}
$ip='src/server/scripts/Scenario/Artifacts/Paladin/BrokenShore/instance_broken_shore.cpp';$actual=Get-PreRagnvaldSecondBattleSource $ip (Get-Content "$repo/$ip" -Raw);$actual=$actual.Replace("`r",'');$prior=(& git -C $repo show "1531780a2:$ip") -join "`n";if($LASTEXITCODE){throw 'Pinned ritual instance missing'}
$expected=$prior.Replace('#include "../../Warrior/Intro/opening_transition.h"','#include "../../Warrior/Intro/opening_transition.h"'+"`n"+'#include "CreatureTextMgr.h"'+"`n"+'#include "../../Warrior/Intro/ritual_transition.h"').Replace('warriorOpening(map) {}','warriorOpening(map), warriorRitual(map) {}').Replace('WarriorOpening::State warriorOpening;','WarriorOpening::State warriorOpening;'+"`n"+'WarriorRitual::State warriorRitual;').Replace('warriorOpening.Observe(creature);','warriorOpening.Observe(creature);'+"`n"+'warriorRitual.Observe(creature);').Replace('warriorFirstWave.Death(creature, killer);','warriorRitual.Death(creature, killer);'+"`n"+'warriorFirstWave.Death(creature, killer);').Replace('if (type == WarriorOpening::SourceData) return warriorOpening.source;','if (type == WarriorOpening::SourceData) return warriorOpening.source;'+"`n"+'if (type == WarriorRitual::DanicaData) return warriorRitual.danica;').Replace('void Update(uint32 diff) override { warriorOpening.Update(diff); warriorTransition.Update(diff); warriorFirstWave.Update(diff); }',"void SetGuidData(uint32 type, ObjectGuid value) override`n        {`n            if (type == WarriorRitual::HitData) warriorRitual.Hit(value);`n        }`n`n        void Update(uint32 diff) override { warriorOpening.Update(diff); warriorTransition.Update(diff); warriorFirstWave.Update(diff); warriorRitual.Update(diff); }")
if((Shape $actual) -cne (Shape $expected)){throw 'Other shared Paladin/instance/first-wave/reinforcement/opening behavior changed'}
if($ScopeOnly){'PASS ritual-only actor replacement and exact instance observe/death/GUID/update bridges; all other actor/opening/Paladin/first-wave/reinforcement bodies retained';return}
if(!$OutputDirectory){$OutputDirectory="$repo/build-extractors/runtime-test/warrior-ritual"};$out=[IO.Path]::GetFullPath($OutputDirectory);New-Item -ItemType Directory -Force $out|Out-Null
[IO.File]::WriteAllText("$out/Danica.inc",$actor+';');[IO.File]::WriteAllText("$out/BaselineDanica.inc",$previous.Replace('npc_danica_the_reclaimer','npc_danica_the_reclaimer_baseline')+';')
Copy-Item "$repo/src/server/scripts/Scenario/Artifacts/Warrior/Intro/ritual_transition.h" "$out/Ritual.inc"
$helper=Get-Content "$repo/src/server/scripts/Scenario/Artifacts/Warrior/Intro/malgalor_finale.h" -Raw
[IO.File]::WriteAllText("$out/Original.inc",'namespace MalgalorFinale {'+(Block $helper 'struct Member')+';'+(Block $helper 'inline uint32 Quest(')+(Block $helper 'inline Player* Original(')+'}')
[IO.File]::WriteAllText("$out/QuestDelay.inc",(Block (Get-Content "$repo/src/server/game/Entities/Player/Player.cpp" -Raw) 'void Player::AddQuestDelayedEvent('))
[IO.File]::WriteAllText("$out/BaseUpdate.inc",(Block (Get-Content "$repo/src/server/game/AI/ScriptedAI/ScriptedCreature.cpp" -Raw) 'void ScriptedAI::UpdateAI('))
$fh=Get-Content "$repo/src/common/Utilities/FunctionProcessor.h" -Raw;$fs=Get-Content "$repo/src/common/Utilities/FunctionProcessor.cpp" -Raw
[IO.File]::WriteAllText("$out/Functions.inc",'typedef std::multimap<uint64, std::function<void()>> FunctionList;'+(Block $fh 'class TC_COMMON_API FunctionProcessor').Replace('TC_COMMON_API ','')+';'+$fs.Substring($fs.IndexOf('FunctionProcessor::FunctionProcessor()')))
$unit=Get-Content "$repo/src/server/game/Entities/Unit/Unit.h" -Raw;[IO.File]::WriteAllText("$out/UnitTimer.inc",(Block $unit 'void AddDelayedEvent('))
if($ExportOnly){return}
$vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
[IO.File]::WriteAllText("$out/run.cmd","@echo off`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`ncl /nologo /EHsc /std:c++17 /W4 /fsanitize=address /Zi /I`"$out`" `"$PSScriptRoot/WarriorRitualTest.cpp`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`" /Fd`"$out/test.pdb`" /link /INCREMENTAL:NO`nif errorlevel 1 exit /b 1`ncd /d `"$out`"`n`"$out/test.exe`"`nexit /b %errorlevel%`n")
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence/$(Get-Date -Format yyyyMMdd-HHmmss-fff)" -RuntimeDirectories @($out) -Test {
 & "$out/run.cmd";if($LASTEXITCODE){throw 'Warrior ritual extracted production ASAN regression failed'}
}
